"""A real bitset for Python, backed by a single arbitrary-precision int."""


class BitSet:
    """Fixed-size bitset backed by one Python int.

    Bits are indexed 0..n-1. Bit i lives at coefficient 2**i of the
    backing integer.
    """

    __slots__ = ("n", "_x")

    def __init__(self, n):
        if not isinstance(n, int):
            raise TypeError("n must be an int")
        if n <= 0:
            raise ValueError("n must be positive")
        self.n = n
        self._x = 0

    # -- basic ops ---------------------------------------------------------

    def set(self, i):
        self._check(i)
        self._x |= 1 << i

    def clear(self, i):
        self._check(i)
        self._x &= ~(1 << i)

    def test(self, i):
        self._check(i)
        return bool((self._x >> i) & 1)

    def count(self):
        return self._x.bit_count()

    # -- iteration / search --------------------------------------------------

    def next_set_bit(self, i):
        """Lowest set bit index >= i, or -1 if none exists."""
        if i < 0:
            raise IndexError("index must be non-negative")
        if i >= self.n:
            return -1
        x = self._x >> i          # drop bits below i
        if x == 0:
            return -1
        v = x & -x                # isolate lowest set bit
        return i + (v.bit_length() - 1)

    def __iter__(self):
        """Yield every set bit index in ascending order."""
        x, i = self._x, 0
        while x:
            v = x & -x            # isolate lowest set bit
            j = i + (v.bit_length() - 1)
            yield j
            x ^= v                # clear it

    # -- boolean algebra -----------------------------------------------------

    def _same_size(self, other):
        if not isinstance(other, BitSet):
            raise TypeError("operand must be a BitSet")
        if other.n != self.n:
            raise ValueError("BitSets must have the same size")

    def __and__(self, other):
        self._same_size(other)
        r = BitSet(self.n)
        r._x = self._x & other._x
        return r

    def __or__(self, other):
        self._same_size(other)
        r = BitSet(self.n)
        r._x = self._x | other._x
        return r

    def __xor__(self, other):
        self._same_size(other)
        r = BitSet(self.n)
        r._x = self._x ^ other._x
        return r

    def __iand__(self, other):
        self._same_size(other)
        self._x &= other._x
        return self

    def __ior__(self, other):
        self._same_size(other)
        self._x |= other._x
        return self

    def __ixor__(self, other):
        self._same_size(other)
        self._x ^= other._x
        return self

    # -- misc -----------------------------------------------------------------

    def _check(self, i):
        if not isinstance(i, int):
            raise TypeError("index must be an int")
        if i < 0 or i >= self.n:
            raise IndexError(f"bit index {i} out of range [0, {self.n})")

    def copy(self):
        r = BitSet(self.n)
        r._x = self._x
        return r

    def __eq__(self, other):
        if not isinstance(other, BitSet):
            return NotImplemented
        return self.n == other.n and self._x == other._x

    def __hash__(self):
        return hash((self.n, self._x))

    def __len__(self):
        return self.count()

    def __repr__(self):
        return f"BitSet(n={self.n}, popcount={self.count()})"

