def set(self, i):
    self._check(i)
    self._x |= 1 << i

def clear(self, i):
    self._check(i)
    self._x &= ~(1 << i)

def test(self, i):
    self._check(i)
    return bool((self._x >> i) & 1)

def update(self, indices):
    """Bulk-set many indices at once.

    Individual set() calls are unavoidably O(n) on an immutable
    int (every |= copies the whole number), so bulk updates go
    through a byte buffer and re-materialize the int once.
    """
    nbytes = (self.n + 7) // 8
    buf = bytearray(self._x.to_bytes(nbytes, "little"))
    for i in indices:
        if i < 0 or i >= self.n:
            raise IndexError(f"bit index {i} out of range [0, {self.n})")
        buf[i >> 3] |= 1 << (i & 7)
    self._x = int.from_bytes(buf, "little")

